B="https://imos-data.s3-ap-southeast-2.amazonaws.com/"; curl -sS -m 60 "$B?list-type=2&delimiter=/&prefix=IMOS/ANMN/Acoustic/" > /tmp/sites.xml; grep -o "<IsTruncated>[^<]*" /tmp/sites.xml; sites=$(grep -o "<Prefix>IMOS/ANMN/Acoustic/[^<]*/</Prefix>" /tmp/sites.xml | sed 's/<[^>]*>//g'); echo "$sites" | tr '\n' ' '; echo; for s in $sites; do curl -sS -m 60 "$B?list-type=2&delimiter=/&prefix=$s" | grep -o "<Prefix>[^<]*</Prefix>" | sed 's/<[^>]*>//g' | grep -E "/(3315|3275|3318)/" ; done; echo ---; curl -sS -m 60 "$B?list-type=2&delimiter=/&prefix=IMOS/ANMN/Acoustic/PAPCA/3318/" | grep -o "<Prefix>[^<]*</Prefix>" | sed 's/<[^>]*>//g' | sed -n '1,3p;$p'; curl -sS -m 60 "$B?list-type=2&delimiter=/&prefix=IMOS/ANMN/Acoustic/PAPCA/3376/" | grep -o "<Prefix>[^<]*</Prefix>" | sed 's/<[^>]*>//g' | sed -n '1,3p;$p'